import Foundation

// MARK: - Worship Content Expansion (Entries 7–20)

extension ContentLibrary {

    static let worshipContentExpansion: [DayContent] = [
        DayContent(
            scriptureReference: "Psalm 95:1-2",
            scriptureText: "Come, let us sing for joy to the Lord; let us shout aloud to the Rock of our salvation. Let us come before him with thanksgiving and extol him with music and song.",
            devotionalTitle: "Come With Joy",
            devotionalText: "Worship isn't reserved for when you feel spiritual. The psalmist issues an invitation — come. Bring your voice, your thanksgiving, your presence. You don't need perfect pitch or a perfect week. God delights in your willingness to show up and praise Him. Today, worship isn't about performance; it's about presence.",
            prayerText: "Lord, I come before You with thanksgiving. You are the Rock of my salvation — steady when everything else shifts. I choose to praise You not because life is perfect, but because You are. Fill my mouth with songs of joy. Let my worship be an offering that pleases Your heart today. In Jesus' name, amen.",
            reflectionPrompt: "What would change if you approached worship as an invitation rather than an obligation?",
            actionSteps: ["Play a worship song and sing along — don't worry about how you sound", "Write down three reasons God is worthy of your praise today"]
        ),
        DayContent(
            scriptureReference: "John 4:23-24",
            scriptureText: "Yet a time is coming and has now come when the true worshipers will worship the Father in the Spirit and in truth, for they are the kind of worshipers the Father seeks.",
            devotionalTitle: "Spirit and Truth",
            devotionalText: "Jesus redefined worship. It's not about location or ritual — it's about authenticity and the Holy Spirit's presence. Worshiping in spirit means engaging your whole heart, not just going through motions. Worshiping in truth means coming honestly, without pretense. God isn't looking for polished performances. He's seeking real people who bring their real selves before a real God.",
            prayerText: "Father, You are seeking worshipers like me — imperfect but honest. Teach me to worship in spirit and truth. Strip away any pretense or performance. I want my worship to be real — rooted in who You truly are and who I truly am before You. Fill me with Your Spirit as I come before You today. In Jesus' name, amen.",
            reflectionPrompt: "Is there any area of your worship life where you're going through motions rather than truly engaging?",
            actionSteps: ["Spend 5 minutes in quiet worship with no music — just your words to God", "Ask the Holy Spirit to reveal one area where you can worship more authentically"]
        ),
        DayContent(
            scriptureReference: "Psalm 100:1-4",
            scriptureText: "Shout for joy to the Lord, all the earth. Worship the Lord with gladness; come before him with joyful songs. Know that the Lord is God. It is he who made us, and we are his; we are his people, the sheep of his pasture.",
            devotionalTitle: "You Belong to Him",
            devotionalText: "This psalm reminds us of a foundational truth: we are His. We didn't make ourselves. We didn't earn our place. We belong to the God who created us and calls us His own. Worship flows naturally when we remember whose we are. You're not an orphan trying to earn approval — you're a beloved child coming home to your Father.",
            prayerText: "Lord, I am Yours. You made me, You know me, and You call me Your own. I worship You with gladness — not because I have to, but because I get to. Thank You for making me part of Your family. I enter Your gates with thanksgiving and Your courts with praise. You are good, and Your love endures forever. In Jesus' name, amen.",
            reflectionPrompt: "How does knowing you belong to God change the way you approach worship?",
            actionSteps: ["Read Psalm 100 aloud as a personal declaration of praise", "Tell someone today about one thing God has done for you"]
        ),
        DayContent(
            scriptureReference: "Psalm 63:1-4",
            scriptureText: "You, God, are my God, earnestly I seek you; I thirst for you, my whole body longs for you, in a dry and parched land where there is no water. I have seen you in the sanctuary and beheld your power and your glory.",
            devotionalTitle: "A Thirst Only God Can Quench",
            devotionalText: "David wrote this psalm in a literal desert, yet his deepest thirst wasn't for water — it was for God. True worship is born from a longing that nothing else can satisfy. When the world feels dry and empty, that ache inside you is actually an invitation to seek God more earnestly. Don't numb the longing — follow it to His presence.",
            prayerText: "God, my soul thirsts for You. In the dry and parched places of my life, You are what I need most. I seek You earnestly — not casually, not half-heartedly. Let me behold Your power and glory today. Satisfy my deepest longings with Your presence alone. Nothing else will do. In Jesus' name, amen.",
            reflectionPrompt: "What are you thirsting for right now, and could that thirst actually be pointing you to God?",
            actionSteps: ["Identify one thing you've been looking to for satisfaction and surrender it to God", "Spend 10 minutes seeking God's presence with no agenda — just be with Him"]
        ),
        DayContent(
            scriptureReference: "Revelation 4:11",
            scriptureText: "You are worthy, our Lord and God, to receive glory and honor and power, for you created all things, and by your will they were created and have their being.",
            devotionalTitle: "He Is Worthy",
            devotionalText: "In heaven, worship isn't complicated. The elders simply declare what is true: God is worthy. Period. Not because of what He does for us, but because of who He is. He created all things by His will. Today, let your worship be less about what you need and more about who He is. Declare His worthiness — not to inform Him, but to remind your own soul.",
            prayerText: "Lord God, You are worthy of all glory, honor, and power. You created all things — the stars, the mountains, and me. By Your will everything exists. I worship You for who You are, not just what You've done. You are holy, You are sovereign, You are beautiful beyond description. Receive my worship today as an offering of love. In Jesus' name, amen.",
            reflectionPrompt: "When was the last time you worshiped God simply for who He is, apart from what He's done for you?",
            actionSteps: ["Write a list of 10 attributes of God and read them aloud as declarations of praise", "Share one attribute of God that amazes you with a friend or family member"]
        ),
        DayContent(
            scriptureReference: "Hebrews 13:15",
            scriptureText: "Through Jesus, therefore, let us continually offer to God a sacrifice of praise — the fruit of lips that openly profess his name.",
            devotionalTitle: "The Sacrifice of Praise",
            devotionalText: "Sometimes worship costs something. When life is hard and praise doesn't come naturally, choosing to worship anyway is a sacrifice. It's easy to praise God on the mountain; the real offering comes in the valley. A sacrifice of praise means worshiping when it hurts, trusting when it's dark, and declaring God's goodness even before you see the evidence.",
            prayerText: "Jesus, I offer You a sacrifice of praise today. Even when it's hard, even when I don't feel like it, I choose to worship. You are good in the valley just as You are on the mountaintop. I profess Your name openly. Help me to praise continually — in the easy moments and especially in the difficult ones. In Jesus' name, amen.",
            reflectionPrompt: "What makes worship feel like a sacrifice right now, and what would it mean to offer it anyway?",
            actionSteps: ["Worship God for 5 minutes about something you're currently struggling with", "Write a psalm of praise from your current circumstances — honest but hopeful"]
        ),
        DayContent(
            scriptureReference: "Psalm 150:1-6",
            scriptureText: "Praise the Lord. Praise God in his sanctuary; praise him in his mighty heavens. Praise him for his acts of power; praise him for his surpassing greatness. Let everything that has breath praise the Lord.",
            devotionalTitle: "Everything That Has Breath",
            devotionalText: "The final psalm is a crescendo of praise — every instrument, every voice, everything that breathes. There's no fine print, no exclusion clause. If you have breath, you qualify to praise God. Your worship doesn't need to be polished or perfect. It just needs to be offered. Today, let everything in you praise the Lord — your words, your work, your relationships, your rest.",
            prayerText: "Lord, I have breath — and I choose to use it to praise You. I praise You for Your acts of power and Your surpassing greatness. Let everything in me worship You today — my thoughts, my words, my actions. I don't want to waste a single breath. Let my whole life be a song of praise to You. In Jesus' name, amen.",
            reflectionPrompt: "If every breath was an opportunity to praise God, how would your day look different?",
            actionSteps: ["Take 5 deep breaths and with each exhale, whisper a different praise to God", "Find one ordinary moment today and turn it into worship"]
        ),
        DayContent(
            scriptureReference: "Psalm 96:1-3",
            scriptureText: "Sing to the Lord a new song; sing to the Lord, all the earth. Sing to the Lord, praise his name; proclaim his salvation day after day. Declare his glory among the nations, his marvelous deeds among all peoples.",
            devotionalTitle: "A New Song",
            devotionalText: "God doesn't want yesterday's worship reheated. He invites you to sing a new song — fresh praise born from today's mercies. Every morning brings new evidence of God's faithfulness, and every new experience gives you new material for worship. Don't just repeat old phrases; let today's gratitude create new expressions of praise.",
            prayerText: "Lord, give me a new song today. Not recycled words, but fresh praise born from what You're doing right now. Your mercies are new every morning, so let my worship be new too. I proclaim Your salvation and declare Your glory. Give me words I haven't spoken yet and melodies my heart hasn't sung. In Jesus' name, amen.",
            reflectionPrompt: "What has God done recently that deserves a fresh expression of worship from you?",
            actionSteps: ["Write your own short worship song, poem, or prayer from today's experience", "Tell someone about something God has done for you this week"]
        ),
        DayContent(
            scriptureReference: "Psalm 29:2",
            scriptureText: "Ascribe to the Lord the glory due his name; worship the Lord in the splendor of his holiness.",
            devotionalTitle: "The Glory Due His Name",
            devotionalText: "God doesn't need our worship to feel good about Himself. But He deserves it. To 'ascribe glory' means to give credit where credit is due — to acknowledge that every good thing comes from Him. Worship is simply telling the truth about God. His holiness is splendid, His name is glorious, and our praise is the most honest thing we can offer.",
            prayerText: "Lord, I ascribe to You the glory due Your name. You are holy — set apart, magnificent, awe-inspiring. Every good thing in my life comes from You. I worship You in the splendor of Your holiness. Open my eyes to see Your glory today — in creation, in Your Word, in the people around me. You deserve all of my praise. In Jesus' name, amen.",
            reflectionPrompt: "Where have you seen God's glory recently that you haven't yet thanked Him for?",
            actionSteps: ["Step outside and find three things in creation that reflect God's glory", "Begin your next prayer by spending the first minute only praising God — no requests"]
        ),
        DayContent(
            scriptureReference: "2 Chronicles 20:21-22",
            scriptureText: "After consulting the people, Jehoshaphat appointed men to sing to the Lord and to praise him for the splendor of his holiness as they went out at the head of the army, saying: 'Give thanks to the Lord, for his love endures forever.'",
            devotionalTitle: "Worship as Warfare",
            devotionalText: "Jehoshaphat faced an impossible battle. His strategy? Put the worship team at the front of the army. It sounds absurd — but when they began to sing, God set ambushes against their enemies. Sometimes the most powerful thing you can do in a battle is worship. Praise shifts the atmosphere. It reminds you who's really fighting for you. Your hardest battles may be won on your knees, not on your feet.",
            prayerText: "Lord, I face battles I cannot win on my own. But like Jehoshaphat, I choose worship as my weapon. I praise You in the face of my fears. I sing in the middle of uncertainty. Your love endures forever, and no enemy can stand against Your presence. Fight for me as I worship You. I trust You with the outcome. In Jesus' name, amen.",
            reflectionPrompt: "What battle in your life needs worship more than worry right now?",
            actionSteps: ["Name your current biggest challenge, then spend 5 minutes worshiping God about it", "Text a friend about a time God came through when things seemed impossible"]
        ),
        DayContent(
            scriptureReference: "Colossians 3:16",
            scriptureText: "Let the message of Christ dwell among you richly as you teach and admonish one another with all wisdom through psalms, hymns, and songs from the Spirit, singing to God with gratitude in your hearts.",
            devotionalTitle: "Worship Together",
            devotionalText: "Worship isn't just a solo activity. Paul describes a community saturated with Christ's message, encouraging one another through song. When believers worship together, something unique happens — faith is strengthened, burdens are shared, and God's presence fills the room. Your worship doesn't just bless God; it encourages the people around you.",
            prayerText: "Lord, let Your message dwell in me richly. Fill my heart with psalms, hymns, and spiritual songs. Give me gratitude that overflows into worship — both alone and with others. Use my praise to encourage those around me. Help me be part of a community that worships You together with wisdom and joy. In Jesus' name, amen.",
            reflectionPrompt: "How does worshiping with others strengthen your faith differently than worshiping alone?",
            actionSteps: ["Share a worship song with a friend and tell them why it means something to you", "Attend a worship gathering this week with the intention of encouraging someone there"]
        ),
        DayContent(
            scriptureReference: "Psalm 34:1",
            scriptureText: "I will extol the Lord at all times; his praise will always be on my lips.",
            devotionalTitle: "At All Times",
            devotionalText: "David wrote this psalm after pretending to be insane to escape an enemy king. His circumstances were humiliating and desperate — yet he declared praise at all times. Not just in good times. Not just on Sundays. Always. This is a decision, not a feeling. You choose to praise before the breakthrough, during the struggle, and after the storm. That kind of worship changes you from the inside out.",
            prayerText: "Lord, I make a decision today: I will praise You at all times. In the morning and at night. In joy and in sorrow. When I understand and when I don't. Your praise will always be on my lips. Help me keep this commitment — not in my own strength, but by Your Spirit. You are worthy of constant praise. In Jesus' name, amen.",
            reflectionPrompt: "What would it look like to make worship a constant rhythm in your life rather than an occasional event?",
            actionSteps: ["Set three alarms today labeled 'Praise' and pause to worship for 60 seconds each time", "Before bed, review your day and find one unexpected moment where God was present"]
        ),
        DayContent(
            scriptureReference: "Isaiah 6:1-3",
            scriptureText: "In the year that King Uzziah died, I saw the Lord, high and exalted, seated on a throne; and the train of his robe filled the temple. Above him were seraphim... And they were calling to one another: 'Holy, holy, holy is the Lord Almighty; the whole earth is full of his glory.'",
            devotionalTitle: "Holy, Holy, Holy",
            devotionalText: "Isaiah had a vision of God's throne room, and it changed everything. The seraphim didn't cry 'loving, loving, loving' or 'powerful, powerful, powerful' — though God is both. They cried 'holy.' God's holiness is the foundation of every other attribute. When we glimpse His holiness, worship isn't optional — it's the only appropriate response. Like Isaiah, an encounter with God's holiness transforms us.",
            prayerText: "Holy, holy, holy Lord God Almighty. The whole earth is full of Your glory. I stand in awe of Your holiness — You are set apart, pure, and magnificent beyond my comprehension. Like Isaiah, I come undone before You. Cleanse me, transform me, send me. Let this encounter with Your holiness change the way I live today. In Jesus' name, amen.",
            reflectionPrompt: "When was the last time you were truly awed by God's holiness?",
            actionSteps: ["Read Isaiah 6:1-8 slowly and imagine yourself in the throne room", "Spend 5 minutes meditating on the word 'holy' and what it means for your life"]
        ),
        DayContent(
            scriptureReference: "Romans 12:1",
            scriptureText: "Therefore, I urge you, brothers and sisters, in view of God's mercy, to offer your bodies as a living sacrifice, holy and pleasing to God — this is your true and proper worship.",
            devotionalTitle: "Your Life as Worship",
            devotionalText: "Paul expands worship far beyond singing. Your true worship is how you live — every choice, every action, every moment offered back to God. A living sacrifice means your whole life becomes an altar. The way you work, love, speak, rest, and serve — all of it can be worship. Today, don't just sing to God. Live for Him.",
            prayerText: "Father, I offer my body as a living sacrifice today. My hands, my feet, my mouth, my mind — all of it is Yours. Let my work be worship. Let my relationships be worship. Let my rest be worship. Transform me by renewing my mind so that every part of my life becomes an offering that pleases You. This is my true worship. In Jesus' name, amen.",
            reflectionPrompt: "What area of your daily life has not yet become an act of worship?",
            actionSteps: ["Choose one routine task today and do it intentionally as an offering to God", "Ask God to show you one habit that doesn't honor Him and take a step toward changing it"]
        ),
    ]
}
